# volume lunare Google RO (Semrush, nov. 2026) — pentru prioritizare
def volumes(path):
    v = {}
    for line in open(path, encoding='utf-8').read().splitlines()[1:]:
        k, vol = line.split(';')[:2]; v[k] = int(vol)
    return v
